package weeklyassignments;

public class Assignment6_EvenorOddNumbers {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int num=20;
		System.out.print("Even numbers:");
		for(int i=1; i<=20;i++)
		{
		if (i%2==0)
		{
			System.out.print(i + " ");
		}
		}
		System.out.print("\nOdd numbers: ");
		for(int i=1; i<=20;i++)
		{
		if (i%2 !=0)
		{
			System.out.print(i + " ");
		}
		
	}
		}
}
